#!/usr/bin/env bash
# Starts/updates Caddy (HTTPS front door), the registry API and the test player.
# Run on the server from /opt/sbradio/app/infra:   bash scripts/up.sh
set -euo pipefail
cd "$(dirname "$0")/.."

ENV_FILE=/opt/sbradio/config/sbradio.env
if [[ ! -f "$ENV_FILE" ]]; then
  echo "Missing $ENV_FILE - copy infra/.env.example there and fill it in." >&2
  exit 1
fi
set -a; source "$ENV_FILE"; set +a

# Player config: points the test player at this server's registry API.
mkdir -p /opt/sbradio/generated
cat > /opt/sbradio/generated/config.js <<EOF
// Generated by infra/scripts/up.sh - do not edit.
window.SBR_CONFIG = { apiBase: 'https://${API_DOMAIN}', preferHls: false, refreshMs: 15000 };
EOF

docker compose --env-file "$ENV_FILE" up -d --build --remove-orphans
docker compose --env-file "$ENV_FILE" ps

echo
echo "AzuraCast : https://${RADIO_DOMAIN}"
echo "API       : https://${API_DOMAIN}/v1/stations"
echo "Player    : https://${PLAYER_DOMAIN}"
